from pathlib import Path
for root in [Path('/workspace/source/incoming'), Path('/workspace/source')]:
    print('ROOT', root)
    if not root.is_dir():
        continue
    for p in sorted(root.iterdir()):
        if p.is_file() and p.suffix in {'.md','.json','.txt'}:
            print(p.stat().st_size, p.name)
